import math
from sdata1 import talk,svg,person,F,SUN,HILL,TEMPLE,B
from sdata2 import lab,crowd,DOOR
D=dict
RF=['śrīveṅkaṭeśacaraṇau','śaraṇaṃ prapadye']
def L(a,b,c,n): return [a,b,c,[RF[0],RF[1]+f' ‖{n}‖']]
def FEET(x=110,y=110,s=1,col='#f2a38a'):
    return f'<g transform="translate({x} {y}) scale({s})" stroke="#111" stroke-width="2.5"><path d="M-34 0 q-6 -40 10 -44 q16 4 10 44 q-4 14 -10 14 q-6 0 -10 -14z" fill="{col}"/><path d="M34 0 q6 -40 -10 -44 q-16 4 -10 44 q4 14 10 14 q6 0 10 -14z" fill="{col}"/>'+''.join(f'<circle cx="{sx*(30-5*k)}" cy="{-46+2*k}" r="3" fill="#fff"/>' for sx in (-1,1) for k in range(5))+'</g>'
V=[
D(n='1',lines=[['īśānāṃ jagato\'sya veṅkaṭapater','viṣṇoḥ parāṃ preyasīṃ'],['tadvakṣaḥsthalanityavāsarasikāṃ','tatkṣāntisaṃvardhinīm |'],['padmālaṅkṛtapāṇipallavayugāṃ','padmāsanasthāṃ śriyaṃ'],['vātsalyādiguṇojjvalāṃ bhagavatīṃ','vande jaganmātaram ‖1‖']],theme='FIRST, TO THE MOTHER',
 svg=svg('Lakshmi seated on a lotus holding lotuses in both hands, glowing with kindness, with the Lord\'s chest behind her',SUN(110,64,44).replace('#ffd60a','#ffe9a0')+'<g stroke="#111" stroke-width="2.5"><circle cx="110" cy="66" r="14" fill="#f2c79b"/><path d="M84 126 q26 -60 52 0z" fill="#e05a8a"/></g><path d="M64 136 q46 -22 92 0 q-46 18 -92 0z" fill="#f08aa6" stroke="#111" stroke-width="2"/>'+''.join(f'<circle cx="{x}" cy="96" r="7" fill="#f08aa6" stroke="#111"/>' for x in (78,142))+lab(110,158,'JAGANMĀTĀ',10),B),
 mean='I bow to Śrī, the Mother of the world: Ruler of this universe; the supreme beloved of Viṣṇu, Lord of Veṅkaṭa; who delights in dwelling for ever on His chest; who makes His forbearance grow; whose tender hands are adorned with lotuses; who is seated on a lotus; the divine one, radiant with motherly love and every other virtue.',
 plain='I bow to Lakṣmī, Mother of the world and Viṣṇu\'s dearest, who lives in His heart and makes Him more forgiving; lotus in hand, seated on a lotus, shining with a mother\'s love.',
 words=[('īśānām','the <b>Ruler</b> (of the universe)'),('parām preyasīm','His <b>supreme beloved</b>'),('vakṣaḥ-sthala','<b>His chest</b>'),('kṣānti-saṃvardhinīm','<b>who increases His forbearance</b>'),('vātsalya','<b>motherly love</b>'),('jagan-mātaram','<b>Mother of the world</b>')],
 deep='<p><b>Surrender begins with Her.</b> Before surrendering at the Lord\'s feet, the devotee surrenders to Lakṣmī. In Śrīvaiṣṇava teaching she is the <b>puruṣakāra</b>, the one who brings the soul to the Lord (see Suprabhātam verse 3).</p><p><b>She makes Him patient.</b> <i>Tat-kṣānti-saṃvardhinī</i>: "she who increases His forbearance." When the Lord might judge, the Mother pleads; His patience with us grows because of Her.</p><p><b>A grander metre.</b> This one verse is in <b>śārdūla-vikrīḍita</b>, "the tiger\'s play", with long 19-syllable lines, fit for the Queen of the universe.</p>',
 cards=('💡 Puruṣakāra','"The one who recommends": Lakṣmī\'s role in bringing souls to the Lord.','💡 Śārdūlavikrīḍita','A stately 19-syllable metre, "the tiger\'s play".'),
 inner='Go to the Lord through the Mother. Her love opens His mercy.',
 talk=('Why start the surrender with Lakṣmī?','She\'s the mother who speaks for us. She even makes the Lord more patient with our faults!'),
 key='Surrender starts with <b>the Mother, who makes Him forgiving</b>.'),
D(n='2',lines=L(['śrīman kṛpājalanidhe','kṛtasarvaloka'],['sarvajña śakta natavatsala','sarvaśeṣin |'],['svāmin suśīla sulabha-','āśritapārijāta'],2),theme='I TAKE REFUGE AT HIS FEET',
 svg=svg('A devotee kneeling with folded hands before two shining feet, with words of the Lord\'s qualities around',FEET(140,96,.9)+person(50,140,'#ff8c1a','#f2c79b',.65)+lab(70,30,'SVĀMĪ · SUŚĪLA · SULABHA',9)+lab(140,152,'CARAṆAU',10),B),
 mean='O Lord with Śrī, ocean of compassion, maker of all worlds; all-knowing, all-powerful, tender to those who bow, master of all; O Lord, of gracious nature, easy to reach, wish-granting tree to those who take refuge: I take the feet of Śrī Veṅkaṭeśa as my refuge.',
 plain='Lord with Lakṣmī, full of mercy, all-knowing, all-powerful, loving, master of all, kind, easy to reach, giver of every wish: I surrender at Your feet.',
 words=[('śrīman','<b>O Lord with Śrī</b>'),('sarvajña · śakta','<b>all-knowing</b> · <b>all-powerful</b>'),('nata-vatsala','<b>tender to those who bow</b>'),('sarva-śeṣin','<b>master of all</b>'),('suśīla · sulabha','<b>gracious</b> · <b>easy to reach</b>'),('śaraṇaṃ prapadye','<b>I take as my refuge</b>')],
 deep='<p><b>The refrain of surrender.</b> From here every verse ends <i>śrī-veṅkaṭeśa-caraṇau śaraṇaṃ prapadye</i>, "I take the feet of Śrī Veṅkaṭeśa as my refuge". It echoes the first half of the Śrīvaiṣṇava <b>Dvaya mantra</b>, "śrīman nārāyaṇa caraṇau śaraṇaṃ prapadye".</p><p><b>Why these qualities?</b> In the tradition\'s reading, they answer our doubts: He knows our need (<i>sarvajña</i>), can help (<i>śakta</i>), loves us despite faults (<i>vatsala</i>), owns us (<i>svāmin</i>), mixes with the lowly (<i>suśīla</i>) and is easy to reach (<i>sulabha</i>).</p><p><b>Prapatti.</b> The word means "falling at" (the feet): surrender.</p>',
 cards=('💡 Dvaya mantra','The two-line Śrīvaiṣṇava mantra of surrender to Śrīman Nārāyaṇa.','💡 Prapatti','Surrender: taking the Lord alone as the means of salvation.'),
 inner='Every doubt about surrender is answered by one of His qualities.',
 talk=('Why list His qualities before surrendering?','Each one answers a worry: does He know? Can He help? Will He mind my faults? Is He too far? No, no, no, no!'),
 key='"Śaraṇaṃ prapadye": <b>I take His feet as my refuge</b>.'),
D(n='3',lines=L(['ānūpurārcitasujāta-','sugandhipuṣpa-'],['saurabhyasaurabhakarau','samasanniveśau |'],['saumyau sadānubhavane\'pi','navānubhāvyau'],3),theme='FEET THAT SCENT THE FLOWERS',
 svg=svg('The Lord\'s feet with anklets, covered with fragrant flowers right up to the anklets, with lines of scent rising',FEET(110,110,1)+''.join(f'<circle cx="{70+12*k}" cy="{124+(k%2)*8}" r="5" fill="{c}" stroke="#111"/>' for k,c in enumerate(['#fff','#f08aa6','#ffd60a','#fff','#f08aa6','#ffd60a','#fff']))+''.join(f'<path d="M{60+30*k} 50 q6 -10 0 -20" fill="none" stroke="#e05a8a" stroke-width="2"/>' for k in range(4))+lab(110,24,'SAURABHYA',10),B),
 mean='Feet worshipped up to the anklets with lovely fragrant flowers, which they make more fragrant still; feet well matched and well placed; gentle; ever enjoyed, yet always new to enjoy: I take the feet of Śrī Veṅkaṭeśa as my refuge.',
 plain='Flowers heaped up to His anklets only become sweeter by touching His feet. Gentle, perfectly formed, always new however often you see them: I surrender at those feet.',
 words=[('ā-nūpura','<b>up to the anklets</b>'),('arcita','<b>worshipped</b>'),('saurabhya-saurabha-karau','<b>making fragrance more fragrant</b>'),('sama-sanniveśau','<b>evenly placed</b>'),('saumyau','<b>gentle</b>'),('nava-anubhāvyau','<b>ever new to enjoy</b>')],
 deep='<p><b>The feet begin.</b> Verses 3–14 describe only the Lord\'s feet, from many angles: their fragrance, colour, marks, softness, glory in the Vedas. It is like a devotee bowing and looking only at the feet.</p><p><b>Fragrance to flowers.</b> Usually flowers scent what they touch; here the feet give their fragrance to the flowers.</p><p><b>Ever new.</b> <i>Sadā anubhavane\'pi navānubhāvyau</i>: seen every day, yet new every time. Anyone who has stood before a loved image knows this.</p>',
 cards=('💡 Pāda-sevā','Service at the Lord\'s feet: one of the nine forms of devotion.','💡 Nūpura','An anklet; the Lord\'s feet are adorned with them.'),
 inner='What is truly loved never grows old.',
 talk=('Feet that make flowers smell better?','That\'s the poet\'s joy: the flowers get their scent from Him, not the other way round.'),
 key='Feet that make flowers sweeter: <b>ever new, however often seen</b>.',
 note='Some texts read ānūpurārpita for ānūpurārcita.'),
D(n='4',lines=L(['sadyovikāsisamuditvara-','sāndrarāga-'],['saurabhyanirbharasaroruha-','sāmyavārtām |'],['samyakṣu sāhasapadeṣu','vilekhayantau'],4),theme='NO LOTUS COMPARES',
 svg=svg('A freshly bloomed red lotus beside the Lord\'s feet, with a big question mark between them',FEET(150,110,.8)+'<g transform="translate(60 120)"><path d="M0 0 q-24 -30 0 -50 q24 20 0 50z" fill="#e05a8a" stroke="#111" stroke-width="2"/><path d="M0 0 q-34 -14 -30 -36 q20 4 30 36z" fill="#f08aa6" stroke="#111"/><path d="M0 0 q34 -14 30 -36 q-20 4 -30 36z" fill="#f08aa6" stroke="#111"/></g>'+f'<text x="104" y="90" text-anchor="middle" {F} font-size="32">?</text>',B),
 mean='Feet that make any talk of their likeness to a lotus, even one just blooming, deep red and full of fragrance, count as a rash exaggeration: I take the feet of Śrī Veṅkaṭeśa as my refuge.',
 plain='Poets compare the Lord\'s feet to fresh red lotuses. These feet make that comparison look silly. I surrender at those feet.',
 words=[('sadyo-vikāsi','<b>just blooming</b>'),('sāndra-rāga','<b>deep red</b>'),('saurabhya-nirbhara','<b>full of fragrance</b>'),('saroruha-sāmya-vārtām','<b>talk of likeness to a lotus</b>'),('sāhasa-padeṣu','<b>among rash words</b>'),('vilekhayantau','<b>causing to be written</b>')],
 deep='<p><b>Beyond comparison.</b> Indian poetry always compares beautiful feet to lotuses. The poet says: with these feet, that comparison is a "rash statement", an overreach.</p><p><b>Writing it down.</b> <i>Vilekhayantau</i>, "causing to be written": the feet themselves enter the lotus-comparison into the list of rash claims. A witty, learned image.</p><p><b>Freshest lotus.</b> Even the best lotus, just opened, deep red, fully fragrant, cannot match them.</p>',
 cards=('💡 Upamā','Simile: the comparison at the heart of Sanskrit poetics.','💡 Vyatireka','A figure of speech where the subject surpasses its comparison.'),
 inner='Words fall short of the divine. Even the best comparison is only a pointer.',
 talk=('A lotus isn\'t good enough?','Not even the freshest, reddest one! Calling His feet "lotus-like" sells them short.'),
 key='No lotus compares <b>to His feet</b>.'),
D(n='5',lines=L(['rekhāmayadhvajasudhākalaśā-','tapatra-'],['vajrāṅkuśāmburuha-','kalpakaśaṅkhacakraiḥ |'],['bhavyair alaṅkṛtatalau','paratattvacihnaiḥ'],5),theme='THE MARKS ON HIS SOLES',
 svg=svg('The soles of two feet with small marks: a flag, a pot, a parasol, a thunderbolt, a goad, a lotus, a tree, a conch and a discus',
  '<g stroke="#111" stroke-width="2.5"><ellipse cx="70" cy="90" rx="34" ry="62" fill="#f2a38a"/><ellipse cx="150" cy="90" rx="34" ry="62" fill="#f2a38a"/></g>'+''.join(f'<text x="{x}" y="{y}" text-anchor="middle" font-size="13">{e}</text>' for x,y,e in [(70,58,'🚩'),(70,82,'🏺'),(70,106,'☂️'),(70,130,'⚡'),(150,52,'🪷'),(150,74,'🌳'),(150,98,'🐚'),(150,122,'☸️'),(150,142,'🔱')]),B),
 mean='Feet whose soles are adorned with auspicious marks drawn in lines: banner, nectar-pot, parasol, thunderbolt, goad, lotus, wish-granting tree, conch and discus, the signs of the Supreme Reality: I take the feet of Śrī Veṅkaṭeśa as my refuge.',
 plain='The soles of His feet carry holy marks: a flag, a pot of nectar, a parasol, a thunderbolt, a goad, a lotus, a wish-tree, a conch and a discus, signs that He is the Supreme. I surrender at those feet.',
 words=[('rekhā-maya','<b>made of lines</b>'),('dhvaja · ātapatra','<b>banner</b> · <b>parasol</b>'),('sudhā-kalaśa','<b>pot of nectar</b>'),('vajra · aṅkuśa','<b>thunderbolt</b> · <b>goad</b>'),('kalpaka','the <b>wish-tree</b>'),('para-tattva-cihnaiḥ','<b>signs of the Supreme</b>')],
 deep='<p><b>Marks of the Supreme.</b> Tradition holds that the Lord\'s soles bear auspicious signs (<i>cihna</i>), like the marks palmists look for, but divine. They prove that these are the feet of the Supreme Reality (<i>para-tattva</i>).</p><p><b>Each sign a promise.</b> The banner of victory, the nectar of immortality, the parasol of protection, the goad that guides the mind, the wish-tree, and the conch and discus of Viṣṇu.</p><p><b>Seen in images.</b> Marks of this kind are often shown on the Lord\'s footprints (<i>pādukā</i>) and on paintings of His feet.</p>',
 cards=('💡 Pāda-cihna','Auspicious marks on a divine being\'s soles.','💡 Pādukā','Sandals or footprints of the Lord or a guru, worshipped in their place.'),
 inner='Every sign on His feet is a promise to the one who holds them.',
 talk=('Marks on the soles of His feet?','Holy signs: flag, nectar-pot, parasol, conch, discus. They show these are the Supreme\'s feet.'),
 key='Banner, parasol, conch, discus: <b>the signs of the Supreme on His soles</b>.',
 note='Lists of the sole-marks differ between texts.'),
D(n='6',lines=L(['tāmrodaradyutiparājita-','padmarāgau'],['bāhyair mahobhir abhibhūta-','mahendranīlau |'],['udyannakhāṃśubhir udasta-','śaśāṅkabhāsau'],6),theme='BETTER THAN RUBIES AND SAPPHIRES',
 svg=svg('A red ruby, a blue sapphire and a crescent moon all looking dim beside the Lord\'s shining feet',FEET(140,110,.85)+'<path d="M30 60 l10 -14 h16 l10 14 l-18 22z" fill="#e63946" stroke="#111" stroke-width="2"/><path d="M30 120 l10 -14 h16 l10 14 l-18 22z" fill="#1d3fb8" stroke="#111" stroke-width="2"/><path d="M80 30 a14 14 0 1 0 10 26 a10 10 0 1 1 -10 -26z" fill="#ddd" stroke="#111"/>'+lab(48,96,'RUBY',8)+lab(48,156,'SAPPHIRE',8),B),
 mean='Feet whose coppery soles outshine rubies; whose radiance above outdoes the finest sapphires; whose rising toenail rays drive away the moon\'s light: I take the feet of Śrī Veṅkaṭeśa as my refuge.',
 plain='His red soles outshine rubies, the dark-blue tops outshine sapphires, and His toenails glow brighter than the moon. I surrender at those feet.',
 words=[('tāmra-udara','<b>copper-red soles</b>'),('padma-rāga','<b>ruby</b>'),('bāhyaiḥ mahobhiḥ','<b>by the outer radiance</b>'),('mahendra-nīla','the <b>finest sapphire</b>'),('nakha-aṃśu','<b>toenail rays</b>'),('śaśāṅka-bhāsa','<b>moonlight</b>')],
 deep='<p><b>Three colours.</b> The soles are red, the tops dark blue like the Lord\'s body, and the toenails white and shining. Each beats a precious thing: ruby, sapphire, moon.</p><p><b>Jewels and the Lord.</b> The poet uses the greatest treasures of the world only to show they are less than His feet.</p><p><b>Nakha-candrikā.</b> "Moonlight of the toenails" is a favourite image in Indian devotional poetry.</p>',
 cards=('💡 Padmarāga','"Lotus-red": the Sanskrit name for ruby.','💡 Indranīla','"Indra\'s blue": sapphire.'),
 inner='The world\'s treasures are bright; the Lord\'s feet are brighter.',
 talk=('Brighter than the moon?','His toenails are! Red soles beat rubies, blue tops beat sapphires. The poet is clearly in love.'),
 key='Ruby, sapphire, moon: <b>all dim beside His feet</b>.'),
D(n='7',lines=L(['sapremabhītikamalākara-','pallavābhyāṃ'],['saṃvāhane\'pi sapadi','klamam ādadhānau |'],['kāntāv avāṅmānasagocara-','saukumāryau'],7),theme='TOO TENDER EVEN FOR LAKṢMĪ\'S HANDS',
 svg=svg('Lakshmi gently massaging the Lord\'s feet with her hands, hesitant and loving',FEET(130,110,.85)+person(50,140,'#e05a8a','#f2c79b',.7)+'<path d="M66 108 q20 -6 34 4" fill="none" stroke="#f2c79b" stroke-width="6"/>'+f'<text x="70" y="40" {F} font-size="16" fill="#e05a8a">♥</text>'+lab(120,24,'SAUKUMĀRYA',10),B),
 mean='Feet that grow tired at once even when gently pressed by Lakṣmī\'s tender hands, held with love and with fear of hurting them; lovely, with a softness beyond the reach of word and mind: I take the feet of Śrī Veṅkaṭeśa as my refuge.',
 plain='His feet are so soft that even Lakṣmī\'s gentle hands, pressing them with love and care, seem to tire them. Their tenderness is beyond words. I surrender at those feet.',
 words=[('sa-prema-bhīti','<b>with love and fear</b>'),('kara-pallava','<b>tender, leaf-like hands</b>'),('saṃvāhane','<b>in massaging</b>'),('sapadi klamam','<b>at once, tiredness</b>'),('avāṅ-mānasa-gocara','<b>beyond word and mind</b>'),('saukumārya','<b>tenderness</b>')],
 deep='<p><b>Love and fear.</b> Lakṣmī presses His feet "with love and fear": love for Him, and fear that even her soft hands might hurt. A tender domestic picture.</p><p><b>Then how did He walk?</b> The devotee\'s heart aches: these same feet walked forests as Rāma and herded cows as Kṛṣṇa. The tradition loves this paradox (see verse 12).</p><p><b>Beyond word and mind.</b> The Upaniṣads use <i>avāṅmanasa-gocara</i> for the Absolute; here it describes the softness of His feet.</p>',
 cards=('💡 Saukumārya','Delicacy, tenderness: one of the Lord\'s bodily beauties.','💡 Saṃvāhana','Gently pressing the feet: an act of loving service.'),
 inner='Serve gently. Even the Mother serves the Lord with love and care.',
 talk=('Lakṣmī\'s hands are too rough?','Not rough, just that His feet are so tender! She presses them with love and a little fear.'),
 key='Feet so tender <b>even Lakṣmī\'s hands are careful</b>.'),
D(n='8',lines=L(['lakṣmīmahītadanurūpa-','nijānubhāva-'],['nīlādidivyamahiṣī-','karapallavānām |'],['āruṇyasaṅkramaṇataḥ kila','sāndrarāgau'],8),theme='RED FROM THE QUEENS\' HANDS',
 svg=svg('Three goddesses, Sri, Bhu and Nila, touching the Lord\'s feet, with red colour flowing from their hands to the feet',FEET(110,120,.75)+person(36,140,'#e05a8a','#f2c79b',.55)+person(184,140,'#2a9d6f','#f2c79b',.55)+person(110,74,'#1d3fb8','#f2c79b',.45)+lab(36,158,'ŚRĪ',8)+lab(184,158,'BHŪ',8)+lab(110,24,'NĪLĀ',8),B),
 mean='Feet deep red, it seems, because the redness of the tender hands of Lakṣmī, Bhū, Nīlā and the other divine queens, each with her own fitting glory, has passed into them: I take the feet of Śrī Veṅkaṭeśa as my refuge.',
 plain='The Lord\'s feet are red, the poet says, because the red of His queens\' hands, Lakṣmī\'s, Bhū\'s, Nīlā\'s, has rubbed off on them as they served. I surrender at those feet.',
 words=[('lakṣmī · mahī','<b>Lakṣmī</b> · <b>Bhū</b>, the Earth'),('nīlā','<b>Nīlā Devī</b>'),('divya-mahiṣī','<b>divine queens</b>'),('āruṇya','<b>redness</b>'),('saṅkramaṇataḥ','<b>by transfer</b>'),('kila','<b>it seems</b>, they say')],
 deep='<p><b>A poet\'s explanation.</b> Why are the soles so red? Because His queens\' rosy hands have touched them so often that the colour has passed over. <i>Kila</i>, "it seems", marks this as a poetic fancy.</p><p><b>Three consorts.</b> Śrīvaiṣṇava tradition names three principal consorts of Viṣṇu: <b>Śrī</b> (Lakṣmī), <b>Bhū</b> (Earth) and <b>Nīlā</b>, identified in the Tamil tradition with Nappinnai, Kṛṣṇa\'s beloved among the cowherds.</p><p><b>Connected to verse 7.</b> There, Lakṣmī massaged His feet; here all the queens do.</p>',
 cards=('💡 Nīlā Devī','The third consort of Viṣṇu in Śrīvaiṣṇava tradition; Nappinnai in Tamil.','💡 Utprekṣā','Poetic fancy: imagining a cause, here for the feet\'s colour.'),
 inner='Love leaves its colour on what it serves.',
 talk=('Why are His feet red?','The poet\'s fancy: the queens\' rosy hands served them so often that the colour rubbed off!'),
 key='Red with the touch of <b>His queens\' loving hands</b>.'),
D(n='9',lines=L(['nityānamadvidhiśivādi-','kirīṭakoṭi-'],['pratyuptadīptanavaratna-','mahaḥprarohaiḥ |'],['nīrājanāvidhim udāram','upādadhānau'],9),theme='THE GODS\' CROWNS WAVE THE LAMP',
 svg=svg('Gods bowing so low that the jewels in their crowns shine on the Lord\'s feet like a waving lamp',FEET(150,110,.75)+''.join(f'<g transform="translate({30+34*k} 110) rotate(-30)"><path d="M-12 0 l4 -14 l8 8 l8 -8 l4 14z" fill="#ffd60a" stroke="#111" stroke-width="2"/><circle cy="-4" r="3" fill="{c}"/></g>' for k,c in enumerate(['#e63946','#1d6fb8','#2a9d6f']))+''.join(f'<path d="M110 {80+10*k} l26 0" stroke="#ffd60a" stroke-width="2"/>' for k in range(4))+lab(110,30,'NĪRĀJANA',11),B),
 mean='Feet that receive a grand āratī from the rising rays of the bright nine gems set in the crowns of Brahmā, Śiva and the other gods, who are always bowing to them: I take the feet of Śrī Veṅkaṭeśa as my refuge.',
 plain='When the gods bow at His feet, the jewels in their crowns flash, and it looks like they are waving a lamp in worship. I surrender at those feet.',
 words=[('nitya-ānamat','<b>always bowing</b>'),('vidhi · śiva','<b>Brahmā</b> · <b>Śiva</b>'),('kirīṭa-koṭi','<b>tips of crowns</b>'),('nava-ratna','the <b>nine gems</b>'),('mahaḥ-prarohaiḥ','<b>by sprouting rays</b>'),('nīrājana','<b>āratī</b>, the lamp-waving')],
 deep='<p><b>An āratī of light.</b> At the end of worship a lamp is waved before the Lord (<i>nīrājana</i>, āratī). Here the gods bow so constantly that the light from their crown-jewels becomes that āratī.</p><p><b>Nava-ratna.</b> The nine gems: ruby, pearl, coral, emerald, yellow sapphire, diamond, blue sapphire, hessonite and cat\'s-eye, each linked with one of the nine planets.</p><p><b>Gods at His feet.</b> As in Suprabhātam verses 14 and 16, the greatest gods are His devotees.</p>',
 cards=('💡 Nīrājana','Waving a lit lamp before the deity: āratī.','💡 Nava-ratna','The nine gems, each tied to one of the nine planets.'),
 inner='When you bow fully, your best becomes an offering of light.',
 talk=('The crowns do the āratī?','The gods bow so often that their crown-jewels sparkle on His feet, like a waving lamp!'),
 key='The gods\' bowing crowns <b>become a lamp of worship</b>.'),
D(n='10',lines=L(['"viṣṇoḥ pade parama" ity','uditapraśaṃsau'],['yau "madhva utsa" iti','bhogyatayāpy upāttau |'],['bhūyas tatheti tava','pāṇitalapradiṣṭau'],10),theme='PRAISED IN THE VEDA, SHOWN BY HIS HAND',
 svg=svg('The Lord with his right hand pointing down to his feet, and a Vedic scroll with a spring of honey beside',
  '<g stroke="#111" stroke-width="2.5"><circle cx="110" cy="40" r="12" fill="#4a7fd0"/><path d="M98 26 h24 v-12 h-24z" fill="#ffd60a"/><path d="M90 130 q-4 -60 20 -76 q24 16 20 76z" fill="#ffd60a"/></g><path d="M126 70 l14 50" stroke="#4a7fd0" stroke-width="6"/>'+FEET(110,146,.35)+'<rect x="10" y="40" width="54" height="40" fill="#fff3b0" stroke="#111" stroke-width="2"/>'+lab(37,56,'ṚG VEDA',7)+lab(37,70,'1.154.5',7)+'<path d="M180 120 q6 -20 12 0 q-6 10 -12 0z" fill="#e0a800" stroke="#111"/>'+lab(186,140,'MADHU',8),B),
 mean='Feet praised in the words "the highest step of Viṣṇu"; feet held to be sweet, as "a spring of honey"; and pointed out again by the palm of Your hand, as if to say "it is so": I take the feet of Śrī Veṅkaṭeśa as my refuge.',
 plain='The Veda praises His feet as "Viṣṇu\'s highest step" and "a spring of honey"; and the Lord\'s own hand points to them, as if to say, "Yes, this is true." I surrender at those feet.',
 words=[('viṣṇoḥ pade parame','"<b>in the highest step of Viṣṇu</b>"'),('madhva utsaḥ','"<b>a spring of honey</b>"'),('bhogyatayā','<b>as something sweet to enjoy</b>'),('bhūyaḥ','<b>again</b>'),('tathā iti','"<b>it is so</b>"'),('pāṇi-tala-pradiṣṭau','<b>pointed out by the palm</b>')],
 deep='<p><b>Two Vedic quotations.</b> Both phrases come from one hymn of the Ṛg Veda (1.154.5), which says that in the highest step of Viṣṇu there is a spring of honey. The poet reads this as the Lord\'s feet.</p><p><b>The pointing hand.</b> The image at Tirumala holds the lower right hand pointing down to the feet. Tradition reads it as the Lord saying "surrender here"; the poet says it confirms the Veda: "it is so".</p><p><b>Waist-deep.</b> A popular reading of the lower left hand on the hip: "the ocean of saṃsāra is only this deep for those who hold My feet".</p>',
 cards=('💡 Ṛg Veda 1.154','The hymn to Viṣṇu\'s three strides, with "the highest step" and "a spring of honey".','💡 Varada-hasta','The hand gesture pointing down to the feet, at Tirumala.'),
 inner='The Lord Himself points the way: to His feet.',
 talk=('His hand points to His feet?','Yes, look at the image at Tirumala! The right hand points down: "Hold these. The Veda is right."'),
 key='The Veda praises them; <b>His own hand points to them</b>.'),
D(n='11',lines=L(['pārthāya tatsadṛśa-','sārathinā tvayaiva'],['yau darśitau svacaraṇau','śaraṇaṃ vrajeti |'],['bhūyo\'pi mahyam iha tau','karadarśitau te'],11),theme='"TAKE REFUGE": TO ARJUNA, AND TO ME',
 svg=svg('Krishna as charioteer pointing to his feet for Arjuna on a chariot, and the same gesture today for a devotee',
  '<rect x="6" y="6" width="100" height="148" fill="#ffe3c4" stroke="#111" stroke-width="2"/><rect x="114" y="6" width="100" height="148" fill="#dfe9f6" stroke="#111" stroke-width="2"/><path d="M20 120 h70 v-30 h-70z" fill="#c9a26b" stroke="#111"/><circle cx="34" cy="128" r="10" fill="#7a5a3a" stroke="#111"/><circle cx="76" cy="128" r="10" fill="#7a5a3a" stroke="#111"/>'+person(40,90,'#4a7fd0','#4a7fd0',.45)+person(74,88,'#e63946','#f2c79b',.45)+person(150,140,'#ff8c1a','#f2c79b',.5)+'<g stroke="#111" stroke-width="2"><circle cx="190" cy="50" r="8" fill="#4a7fd0"/><path d="M178 110 q-2 -40 12 -52 q14 12 12 52z" fill="#ffd60a"/></g>'+lab(56,148,'GĪTĀ 18.66',9)+lab(164,24,'TODAY',9),B),
 mean='The very feet You showed to Arjuna, You who became his fitting charioteer, saying "take refuge"; those same feet of Yours You show to me again, here, with Your hand: I take the feet of Śrī Veṅkaṭeśa as my refuge.',
 plain='On the battlefield, as Arjuna\'s charioteer, You told him: "Take refuge in Me." Here at Tirumala You point to the same feet for me. I surrender at those feet.',
 words=[('pārthāya','<b>to Pārtha</b>, Arjuna'),('sārathinā','<b>by the charioteer</b>'),('śaraṇaṃ vraja','"<b>take refuge</b>"'),('bhūyo\'pi','<b>once again</b>'),('mahyam iha','<b>to me, here</b>'),('kara-darśitau','<b>shown by the hand</b>')],
 deep='<p><b>The Gītā\'s last word.</b> In Bhagavad Gītā 18.66, Kṛṣṇa tells Arjuna: give up all other ways, take refuge in Me alone, and I will free you. The Śrīvaiṣṇava tradition calls it the <b>Carama Śloka</b>, the final verse.</p><p><b>Then and now.</b> The poet joins Kurukṣetra and Tirumala: what Kṛṣṇa said in words, Veṅkaṭeśa says with His hand, pointing to His feet.</p><p><b>Fitting charioteer.</b> <i>Tat-sadṛśa</i>: Kṛṣṇa became a humble driver worthy of His friend. The Lord of all serves His devotee.</p>',
 cards=('💡 Carama Śloka','Gītā 18.66: "Take refuge in Me alone; I will free you."','💡 Pārtha','"Son of Pṛthā": Arjuna.'),
 inner='The promise made to Arjuna is made to every one of us.',
 talk=('Like the Gītā?','Exactly: "take refuge in Me". Kṛṣṇa said it to Arjuna; Veṅkaṭeśa shows it to us with His hand.'),
 key='Told to Arjuna, <b>shown to me: "take refuge"</b>.'),
D(n='12',lines=L(['manmūrdhni kāliyaphaṇe','vikaṭāṭavīṣu'],['śrīveṅkaṭādriśikhare','śirasi śrutīnām |'],['citte\'py ananyamanasāṃ','samam āhitau te'],12),theme='WHERE HIS FEET HAVE STOOD',
 svg=svg('Six small scenes: the feet on a devotee\'s head, on the hood of a serpent, in a forest, on a hill, on a Veda scroll, and in a heart',
  ''.join(f'<g transform="translate({38+72*(k%3)} {44+70*(k//3)})"><rect x="-32" y="-30" width="64" height="56" fill="#fff" stroke="#111" stroke-width="2"/><text y="2" text-anchor="middle" font-size="18">{e}</text>'+f'<text y="20" text-anchor="middle" {F} font-size="7">{t}</text></g>' for k,(e,t) in enumerate([('🙇','MY HEAD'),('🐍','KĀLIYA'),('🌲','FORESTS'),('⛰️','VEṄKAṬA'),('📜','VEDAS'),('❤️','HEARTS')])),B),
 mean='Your feet, placed alike on my head, on the hood of Kāliya, in the wild forests, on the peak of Veṅkaṭa hill, on the head of the Vedas, and in the hearts of those devoted to nothing else: I take the feet of Śrī Veṅkaṭeśa as my refuge.',
 plain='His feet rest on my head, on the serpent Kāliya\'s hood, in the rough forests, on Veṅkaṭa hill, on the Upaniṣads and in loving hearts, all the same. I surrender at those feet.',
 words=[('mat-mūrdhni','<b>on my head</b>'),('kāliya-phaṇe','<b>on Kāliya\'s hood</b>'),('vikaṭa-aṭavīṣu','<b>in wild forests</b>'),('śirasi śrutīnām','<b>on the head of the Vedas</b>'),('ananya-manasām','<b>of the single-minded</b>'),('samam āhitau','<b>placed equally</b>')],
 deep='<p><b>A journey of the feet.</b> Kṛṣṇa danced on the hood of the serpent Kāliya; Rāma walked barefoot through the forests in exile; the Lord stands on Veṅkaṭa hill; the Upaniṣads ("head of the Vedas") rest on Him; and He lives in loving hearts.</p><p><b>"On my head" first.</b> The devotee puts himself first in the list, alongside a serpent and the Vedas: grace treats all alike (<i>samam</i>).</p><p><b>Recalling verse 7.</b> Feet too tender for Lakṣmī\'s hands walked rough forests: the tradition marvels at this love.</p>',
 cards=('💡 Kāliya','The many-headed serpent in the Yamunā, subdued by young Kṛṣṇa dancing on his hoods.','💡 Śruti-śiras','"Head of the Vedas": the Upaniṣads.'),
 inner='His feet rest equally on the great and the small. Offer your head too.',
 talk=('On a serpent and on my head, the same?','That\'s His grace: Kāliya, the forests, the Vedas, our hearts. He treats them all alike.'),
 key='On Kāliya, on the Vedas, <b>and on my head</b>.'),
D(n='13',lines=L(['amlānahṛṣyad avanītala-','kīrṇapuṣpau'],['śrīveṅkaṭādriśikharā-','bharaṇāyamānau |'],['ānanditākhilamano-','nayanau tavaitau'],13),theme='THE HILL\'S OWN ORNAMENT',
 svg=svg('The Lord\'s feet on top of a green hill like a jewel, with fresh flowers springing up on the ground where they stand',HILL+FEET(110,96,.5)+''.join(f'<circle cx="{40+22*k}" cy="{120-(k%3)*6}" r="4" fill="{c}" stroke="#111"/>' for k,c in enumerate(['#f08aa6','#ffd60a','#fff','#f08aa6','#ffd60a','#fff','#f08aa6']))+lab(110,30,'ŚIKHARA-ĀBHARAṆA',10),B),
 mean='Your feet, which scatter unfading, joyful flowers over the earth; which are the jewel adorning the peak of Śrī Veṅkaṭa hill; which delight every mind and every eye: I take the feet of Śrī Veṅkaṭeśa as my refuge.',
 plain='Wherever His feet step, fresh, happy flowers seem to spring up; they are the jewel on top of Veṅkaṭa hill, and every heart and eye rejoices in them. I surrender at those feet.',
 words=[('amlāna','<b>unfading</b>'),('hṛṣyat','<b>joyful</b>, blooming'),('avanī-tala','<b>the earth\'s surface</b>'),('kīrṇa-puṣpau','<b>strewing flowers</b>'),('ābharaṇāyamānau','<b>serving as an ornament</b>'),('ānandita-akhila','<b>delighting all</b>')],
 deep='<p><b>Flowers where He walks.</b> The ground blooms at the touch of His feet, and the flowers never fade.</p><p><b>The hill\'s jewel.</b> A crown is the ornament of a head; His feet are the crown-jewel of the hill\'s peak. So the hill is honoured by Him, as Suprabhātam verse 15 honoured its names.</p><p><b>For all eyes.</b> <i>Ānandita-akhila-mano-nayanau</i>: all minds and all eyes, with no exceptions.</p>',
 cards=('💡 Ābharaṇa','An ornament, jewellery.','💡 Śikhara','A peak; also the tower crowning a temple.'),
 inner='Where the Lord stands, even rock becomes a garden.',
 talk=('Flowers spring up where He steps?','In the poem, yes, and they never fade. His feet are the hill\'s jewel.'),
 key='Flowers where He steps: <b>the jewel on the hill\'s crown</b>.'),
D(n='14',lines=L(['prāyaḥ prapannajanatā-','prathamāvagāhyau'],['mātuḥ stanāv iva śiśor','amṛtāyamānau |'],['prāptau parasparatulām','atulāntarau te'],14),theme='LIKE A MOTHER TO A CHILD',
 svg=svg('A mother holding her baby close, and beside it the Lord\'s two feet, matched only with each other',person(60,140,'#e05a8a','#f2c79b',.8)+'<circle cx="74" cy="104" r="9" fill="#f2c79b" stroke="#111" stroke-width="2"/>'+FEET(160,110,.7)+f'<text x="160" y="150" text-anchor="middle" {F} font-size="16">=</text>'+lab(110,24,'AMṚTA',11),B),
 mean='Feet which those who surrender reach for first, as a rule; which are like nectar to them, as a mother\'s breast is to her baby; matched only with each other, and with nothing else: I take the feet of Śrī Veṅkaṭeśa as my refuge.',
 plain='Those who surrender go first to His feet, as a baby goes to its mother for milk. Only one foot can be compared to the other; nothing else compares. I surrender at those feet.',
 words=[('prapanna-janatā','<b>the surrendered</b>'),('prathama-avagāhyau','<b>first to be plunged into</b>'),('mātuḥ stanau','<b>a mother\'s breasts</b>'),('śiśoḥ','<b>for a baby</b>'),('paraspara-tulām','<b>comparable to each other</b>'),('atula-antarau','<b>beyond other comparison</b>')],
 deep='<p><b>The baby knows.</b> A newborn needs no teaching to find its mother; the surrendered soul turns to His feet just as naturally. And as milk is life to the baby, the feet are nectar to the devotee.</p><p><b>Only each other.</b> In verse 4 no lotus could compare; here the poet concludes: the right foot can be compared only to the left, and nothing else.</p><p><b>Two in all.</b> The verses on the feet always say <i>caraṇau</i>, dual: the two feet, a pair, like the Lord and Lakṣmī.</p>',
 cards=('💡 Prapanna','One who has surrendered to the Lord.','💡 Ananvaya','The figure of speech where something is compared only to itself.'),
 inner='Come to Him like a child to its mother: without reasons, without fear.',
 talk=('Compared only to each other?','Nothing else is good enough: not lotuses, not jewels. The left foot matches the right, and that\'s it!'),
 key='Nectar to the surrendered, <b>like a mother to her child</b>.'),
D(n='15',lines=L(['sattvottaraiḥ satata-','sevyapadāmbujena'],['saṃsāratārakadayārdra-','dṛgañcalena |'],['saumyopayantṛmuninā','mama darśitau te'],15),theme='SHOWN TO ME BY MY TEACHER',
 svg=svg('A saintly teacher in ochre robes gently pointing a disciple toward the Lord\'s feet on the hill',HILL+FEET(170,90,.45)+person(70,140,'#ff8c1a','#f2c79b',.75)+person(120,146,'#fff','#f2c79b',.5)+'<path d="M84 104 l60 -16" stroke="#111" stroke-width="2" stroke-dasharray="4 3"/>'+lab(70,26,'ĀCĀRYA',11),B),
 mean='Your feet, shown to me by the gentle sage Maṇavāḷa Māmuni, whose lotus feet are always served by the pure-hearted, and whose glance, moist with compassion, carries souls across saṃsāra: I take the feet of Śrī Veṅkaṭeśa as my refuge.',
 plain='My teacher, the gentle Maṇavāḷa Māmuni, whose kind glance carries people across the sea of life, showed me Your feet. I surrender at those feet.',
 words=[('sattva-uttaraiḥ','<b>by the pure-hearted</b>'),('satata-sevya','<b>always to be served</b>'),('saṃsāra-tāraka','<b>carrying across saṃsāra</b>'),('dayā-ārdra','<b>moist with compassion</b>'),('dṛg-añcala','the <b>corner of the eye</b>, a glance'),('saumya-upayantṛ-muni','<b>Saumya Jāmātṛ Muni</b>: Maṇavāḷa Māmuni')],
 deep='<p><b>The guru.</b> <i>Saumyopayantṛ-muni</i> is a Sanskrit rendering of the Tamil name <b>Maṇavāḷa Māmuni</b> ("bridegroom-sage", Saumya Jāmātṛ Muni): the poet\'s own teacher, who asked him to compose this hymn.</p><p><b>Through the ācārya.</b> In Śrīvaiṣṇava practice, one comes to the Lord\'s feet through one\'s teacher. Prapatti is usually performed under an ācārya\'s guidance.</p><p><b>A glance that saves.</b> <i>Dayārdra-dṛgañcala</i>: the merest sidelong look of the compassionate teacher is enough to carry one across.</p>',
 cards=('💡 Maṇavāḷa Māmuni','A 14th–15th-century Śrīvaiṣṇava teacher, revered as a later form of Rāmānuja.','💡 Ācārya','A spiritual teacher who guides the disciple to the Lord.'),
 inner='Thank the one who showed you the way. Gratitude to the teacher is part of the path.',
 talk=('Who is this sage?','The poet\'s own guru, Maṇavāḷa Māmuni. He\'s saying: my teacher showed me these feet.'),
 key='My teacher <b>showed me His feet</b>.'),
D(n='16',lines=[['śrīśa śriyā ghaṭikayā','tvadupāyabhāve'],['prāpye tvayi svayam','upeyatayā sphurantyā |'],['nityāśritāya niravadya-','guṇāya tubhyaṃ'],['syāṃ kiṅkaro vṛṣagirīśa','na jātu mahyam ‖16‖']],theme='YOUR SERVANT, NEVER MY OWN',
 svg=svg('A devotee serving the Lord and Lakshmi together, holding a lamp, with no thought of himself',SUN(110,60,40).replace('#ffd60a','#ffe9a0')+'<g stroke="#111" stroke-width="2.5"><circle cx="128" cy="50" r="12" fill="#4a7fd0"/><path d="M116 36 h24 v-12 h-24z" fill="#ffd60a"/><path d="M108 120 q-4 -50 20 -62 q24 12 20 62z" fill="#ffd60a"/></g>'+person(86,120,'#e05a8a','#f2c79b',.55)+person(50,146,'#ff8c1a','#f2c79b',.55)+'<g transform="translate(70 120)"><path d="M-8 0 h16 l-3 5 h-10z" fill="#e0a800" stroke="#111"/><path d="M0 0 q-5 -10 0 -15 q5 5 0 15z" fill="#ff8c1a"/></g>'+lab(110,152,'KAIṄKARYA',10),B),
 mean='O Lord of Śrī: with Śrī as the one who brings us together; with You as the means; and with You, together with Her, shining as the goal to be reached: to You, always one with Her, of flawless virtues, may I be a servant, O Lord of Vṛṣa hill, and never for my own sake.',
 plain='Lakṣmī brings me to You; You are the way; You with Her are the goal. Let me serve You, perfect Lord, forever, and never for myself.',
 words=[('śrīśa','<b>O Lord of Śrī</b>'),('ghaṭikayā','<b>as the one who unites</b>'),('upāya','the <b>means</b>'),('upeya','the <b>goal</b>'),('kiṅkaraḥ syām','<b>may I be a servant</b>'),('na jātu mahyam','<b>never for myself</b>')],
 deep='<p><b>The whole teaching in one verse.</b> Śrī brings the soul to Him (<i>ghaṭikā</i>, the one who unites); He alone is the means (<i>upāya</i>); He, with Śrī, is the goal (<i>upeya</i>). The poet\'s wish: to serve Him forever.</p><p><b>"Never for myself."</b> The second half of the Dvaya mantra ends <i>śrīmate nārāyaṇāya namaḥ</i>; tradition reads <i>namaḥ</i> as <i>na mama</i>, "not mine". "Na jātu mahyam" says the same: service with no self in it.</p><p><b>The Prapatti\'s arc.</b> It began with Śrī (verse 1), passed through His feet (2–14) and the teacher (15), and ends in selfless service: <i>kaiṅkarya</i>.</p>',
 cards=('💡 Upāya · Upeya','The means and the goal: in prapatti, both are the Lord.','💡 Kaiṅkarya','Loving service, the Śrīvaiṣṇava\'s highest aim.'),
 inner='Serve without keeping anything back for yourself. That is surrender.',
 talk=('"Never for myself"?','Even our service should not be about us. Not "I gain", only "He is pleased". That\'s the end of the Prapatti.'),
 key='"Syāṃ kiṅkaraḥ": <b>may I serve You, never for myself</b>.'),
]
